BEGIN;
-- Normalized signed, immutable subledger events. Current source state is deliberately not a historical filter.
CREATE FUNCTION encova_finance_ageing_events(side TEXT,cutoff DATE) RETURNS TABLE(id UUID,"documentId" UUID,"partyId" UUID,"accountId" UUID,"journalId" UUID,"effectiveDate" DATE,kind TEXT,amount NUMERIC,number TEXT,reference TEXT,"documentDate" DATE,"dueDate" DATE,"originalAmount" NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT v.id,v."invoiceId",v."partyId",v."accountId",v."journalId",v."effectiveDate",v.kind,v.amount,i.number,i.reference,i."invoiceDate",i."dueDate",i."totalAmount" FROM public."FinanceReceivableEvent" v JOIN public."FinanceInvoice" i ON i.id=v."invoiceId" WHERE side='AR' AND v."effectiveDate"<=cutoff
 UNION ALL SELECT v.id,v."billId",v."partyId",v."accountId",v."journalId",v."effectiveDate",v.kind,v.amount,i.number,i.reference,i."billDate",i."dueDate",i."totalAmount" FROM public."FinancePayableEvent" v JOIN public."FinanceBill" i ON i.id=v."billId" WHERE side='AP' AND v."effectiveDate"<=cutoff
$$;
CREATE FUNCTION encova_finance_ageing_documents(side TEXT,cutoff DATE) RETURNS TABLE(id UUID,"partyId" UUID,"accountId" UUID,number TEXT,reference TEXT,"documentDate" DATE,"dueDate" DATE,"originalAmount" NUMERIC,"openAmount" NUMERIC,"daysPastDue" INTEGER,bucket TEXT,"eventCount" INTEGER) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 WITH docs AS(SELECT "documentId" AS id,"partyId","accountId",number,reference,"documentDate","dueDate","originalAmount",sum(amount) AS open,count(*)::integer AS events FROM public.encova_finance_ageing_events(side,cutoff) GROUP BY "documentId","partyId","accountId",number,reference,"documentDate","dueDate","originalAmount")
 SELECT id,"partyId","accountId",number,reference,"documentDate","dueDate","originalAmount",open,greatest(0,cutoff-"dueDate"),CASE WHEN cutoff<="dueDate" THEN 'NOT_DUE' WHEN cutoff-"dueDate"<=30 THEN 'DAYS_1_30' WHEN cutoff-"dueDate"<=60 THEN 'DAYS_31_60' WHEN cutoff-"dueDate"<=90 THEN 'DAYS_61_90' ELSE 'OVER_90' END,events FROM docs
$$;
CREATE FUNCTION encova_finance_ageing_report(side TEXT,cutoff DATE,search TEXT,requested_page INTEGER,issue_page INTEGER,include_settled BOOLEAN,bucket_filter TEXT) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;BEGIN
 WITH docs AS MATERIALIZED(SELECT d.*,p.name AS "partyName",a.code AS "accountCode",a.name AS "accountName",a.active AS "accountActive" FROM public.encova_finance_ageing_documents(side,cutoff)d JOIN public."FinanceParty" p ON p.id=d."partyId" JOIN public."FinanceAccount" a ON a.id=d."accountId"),
 totals AS(SELECT coalesce(sum("openAmount"),0) AS open,count(*) FILTER(WHERE "openAmount"<>0)::integer AS open_docs,count(*) FILTER(WHERE "openAmount"<0)::integer AS negative_docs,coalesce(sum("openAmount") FILTER(WHERE bucket='NOT_DUE'),0) AS not_due,coalesce(sum("openAmount") FILTER(WHERE bucket='DAYS_1_30'),0) AS days_1_30,coalesce(sum("openAmount") FILTER(WHERE bucket='DAYS_31_60'),0) AS days_31_60,coalesce(sum("openAmount") FILTER(WHERE bucket='DAYS_61_90'),0) AS days_61_90,coalesce(sum("openAmount") FILTER(WHERE bucket='OVER_90'),0) AS over_90 FROM docs),
 controls AS MATERIALIZED(SELECT a.id,a.code,a.name,a.active,coalesce((SELECT sum(CASE WHEN side='AR' THEN l.debit-l.credit ELSE l.credit-l.debit END) FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=a.id AND e."postingDate"<=cutoff),0) AS gl,coalesce((SELECT sum("openAmount") FROM docs WHERE "accountId"=a.id),0) AS subledger,(SELECT count(*)::integer FROM docs WHERE "accountId"=a.id AND "openAmount"<0) AS negatives FROM public."FinanceAccount" a WHERE a."controlType"=CASE WHEN side='AR' THEN 'RECEIVABLES' ELSE 'PAYABLES' END AND a.currency='PKR'),
 issues AS MATERIALIZED(SELECT *,subledger-gl AS difference FROM controls WHERE subledger<>gl OR negatives>0),issue_counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM issues),ip AS(SELECT *,least(issue_page,pages) AS page FROM issue_counts),bounded_issues AS(SELECT * FROM issues ORDER BY code,id LIMIT 25 OFFSET((SELECT page FROM ip)-1)*25),issue_rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',id,'code',code,'name',name,'active',active,'subledgerBalance',round(subledger,2)::text,'controlBalance',round(gl,2)::text,'difference',round(difference,2)::text,'negativeDocuments',negatives) ORDER BY code,id),'[]'::jsonb) AS items FROM bounded_issues),
 displayed AS MATERIALIZED(SELECT * FROM docs WHERE(include_settled OR "openAmount"<>0) AND(bucket_filter='ALL' OR bucket=bucket_filter) AND concat_ws(' ',number,reference,"partyName","accountCode") ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY "dueDate",number,id LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg((to_jsonb(b)-ARRAY['originalAmount','openAmount'])||jsonb_build_object('originalAmount',round(b."originalAmount",2)::text,'openAmount',round(b."openAmount",2)::text) ORDER BY b."dueDate",b.number,b.id),'[]'::jsonb) AS items FROM bounded b),
 proof AS(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('id',id,'date',"effectiveDate",'amount',amount::text,'journalId',"journalId") ORDER BY id),'[]'::jsonb)::text,'UTF8')),'hex') AS digest FROM public.encova_finance_ageing_events(side,cutoff)),control_totals AS(SELECT coalesce(sum(gl),0) AS gl,coalesce(sum(subledger),0) AS subledger FROM controls)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(DATE '0001-01-01',cutoff,jsonb_build_object('report',side||'_AGEING','asOf',cutoff,'displaySearch',search,'displayBucket',bucket_filter,'includeSettled',include_settled,'subledgerDigest',proof.digest)),'side',side,'totals',jsonb_build_object('openAmount',round(t.open,2)::text,'openDocumentCount',t.open_docs,'notDue',round(t.not_due,2)::text,'days1To30',round(t.days_1_30,2)::text,'days31To60',round(t.days_31_60,2)::text,'days61To90',round(t.days_61_90,2)::text,'over90',round(t.over_90,2)::text),'reconciliation',jsonb_build_object('ready',ip.total=0 AND t.negative_docs=0,'subledgerTotal',round(c.subledger,2)::text,'controlTotal',round(c.gl,2)::text,'difference',round(c.subledger-c.gl,2)::text,'issueCount',ip.total,'negativeDocumentCount',t.negative_docs,'issues',issue_rows.items,'page',ip.page,'pages',ip.pages),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM totals t CROSS JOIN control_totals c CROSS JOIN ip CROSS JOIN issue_rows CROSS JOIN proof CROSS JOIN paging CROSS JOIN rows;RETURN result;
END $$;
CREATE FUNCTION encova_finance_ageing_history(side TEXT,cutoff DATE,document_id UUID,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;BEGIN
 WITH actual AS MATERIALIZED(SELECT v.*,sum(v.amount) OVER(ORDER BY v."effectiveDate",v."journalId",v.id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running FROM public.encova_finance_ageing_events(side,cutoff)v WHERE v."documentId"=document_id),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM actual),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM actual ORDER BY "effectiveDate","journalId",id LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'journalId',b."journalId",'effectiveDate',b."effectiveDate",'kind',b.kind,'amount',round(b.amount,2)::text,'runningBalance',round(b.running,2)::text,'sourceType',e."sourceType",'sourceId',e."sourceId",'reference',e.reference) ORDER BY b."effectiveDate",b."journalId",b.id),'[]'::jsonb) AS items FROM bounded b JOIN public."FinanceJournalEntry" e ON e.id=b."journalId")
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(DATE '0001-01-01',cutoff,jsonb_build_object('report',side||'_AGEING_HISTORY','documentId',document_id)),'side',side,'document',(SELECT (to_jsonb(d)-ARRAY['originalAmount','openAmount'])||jsonb_build_object('originalAmount',round(d."originalAmount",2)::text,'openAmount',round(d."openAmount",2)::text) FROM public.encova_finance_ageing_documents(side,cutoff)d WHERE d.id=document_id),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM paging CROSS JOIN rows;
 IF result->'document'='null'::jsonb THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;RETURN result;
END $$;
CREATE FUNCTION encova_finance_ageing_read(actor UUID,kind TEXT,input JSONB) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE cutoff DATE;side TEXT;requested_page INTEGER;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 IF kind IS NULL OR kind NOT IN('REPORT_AR','REPORT_AP','HISTORY_AR','HISTORY_AP') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR jsonb_typeof(input->'asOf') IS DISTINCT FROM 'string' OR input->>'asOf'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR jsonb_typeof(input->'page') IS DISTINCT FROM 'number' OR(input->>'page')::integer NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 cutoff:=(input->>'asOf')::date;IF cutoff<DATE '0001-01-01' OR cutoff>DATE '9999-12-31' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;side:=right(kind,2);requested_page:=(input->>'page')::integer;
 IF kind LIKE 'HISTORY_%' THEN
  IF input-ARRAY['asOf','page','documentId']<>'{}'::jsonb OR jsonb_typeof(input->'documentId') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  RETURN public.encova_finance_ageing_history(side,cutoff,(input->>'documentId')::uuid,requested_page);
 END IF;
 IF input-ARRAY['asOf','page','q','issuePage','includeSettled','bucket']<>'{}'::jsonb OR jsonb_typeof(input->'q') IS DISTINCT FROM 'string' OR length(input->>'q')>100 OR jsonb_typeof(input->'issuePage') IS DISTINCT FROM 'number' OR(input->>'issuePage')::integer NOT BETWEEN 1 AND 10000 OR jsonb_typeof(input->'includeSettled') IS DISTINCT FROM 'string' OR input->>'includeSettled' NOT IN('YES','NO') OR jsonb_typeof(input->'bucket') IS DISTINCT FROM 'string' OR input->>'bucket' NOT IN('ALL','NOT_DUE','DAYS_1_30','DAYS_31_60','DAYS_61_90','OVER_90') THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 RETURN public.encova_finance_ageing_report(side,cutoff,input->>'q',requested_page,(input->>'issuePage')::integer,input->>'includeSettled'='YES',input->>'bucket');
 EXCEPTION WHEN data_exception THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END $$;
DO $$ DECLARE f RECORD;r TEXT;BEGIN
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'encova_finance_ageing_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);FOREACH r IN ARRAY ARRAY['encova_app','anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,r);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION public.encova_finance_ageing_read(UUID,TEXT,JSONB) TO encova_app;END IF;
END $$;
COMMIT;
